-- DataSub commercial identity and upgrade policy.
update public.datasub_upgrade_offers set base_price=30000,name='Reseller',description='Request a branded IHLink-powered reseller website. The one-time website build/setup fee is NGN 30,000 after approval.',promo_discount_percent=0,promo_starts_at=null,promo_ends_at=null,updated_at=now() where code='reseller';
update public.datasub_upgrade_offers set base_price=0,name='API User',description='Request DataSub API access for an existing website or application. There is no API upgrade fee; approval is based on submitted website/business details and API terms.',promo_discount_percent=0,promo_starts_at=null,promo_ends_at=null,target_tier_code=null,api_access=true,updated_at=now() where code='api_developer';
update public.datasub_upgrade_offers set base_price=0,promo_discount_percent=0,promo_starts_at=null,promo_ends_at=null,is_active=false,description='Top Seller is awarded by IHLink administrators based on reseller performance and is not a purchasable upgrade.',updated_at=now() where code='top_seller';
alter table public.datasub_upgrade_requests add column if not exists website_url text, add column if not exists contact_channel text, add column if not exists request_notes text;
alter table public.datasub_reseller_accounts add column if not exists api_access_approved boolean not null default false, add column if not exists api_website_url text, add column if not exists api_approved_by uuid references public.profiles(id), add column if not exists api_approved_at timestamptz;
create or replace function public.review_datasub_upgrade_request(p_request_id uuid,p_approve boolean) returns void language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare v_request public.datasub_upgrade_requests%rowtype; v_offer public.datasub_upgrade_offers%rowtype; v_profile public.profiles%rowtype; begin if auth.uid() is null or not private.has_product_access('datasub','approve') then raise exception 'DataSub approval permission required'; end if; select * into v_request from public.datasub_upgrade_requests where id=p_request_id for update; if not found then raise exception 'Upgrade request not found'; end if; if v_request.status<>'pending' then raise exception 'Upgrade request has already been reviewed'; end if; select * into v_offer from public.datasub_upgrade_offers where code=v_request.offer_code; if not found then raise exception 'Upgrade offer not found'; end if; select * into v_profile from public.profiles where id=v_request.user_id; if p_approve then if v_request.offer_code='api_developer' then insert into public.datasub_reseller_accounts(user_id,business_name,phone,tier_code,status,api_access_approved,api_website_url,api_approved_by,api_approved_at,approved_by,approved_at) values(v_request.user_id,coalesce(nullif(trim(concat_ws(' ',v_profile.first_name,v_profile.last_name)),''),'IHLink API User'),coalesce(nullif(v_profile.phone,''),'Not provided'),'bronze','active',true,v_request.website_url,auth.uid(),now(),auth.uid(),now()) on conflict(user_id) do update set api_access_approved=true,api_website_url=excluded.api_website_url,api_approved_by=auth.uid(),api_approved_at=now(),status='active',updated_at=now(); elsif v_request.offer_code='reseller' then insert into public.datasub_reseller_accounts(user_id,business_name,phone,tier_code,status,approved_by,approved_at) values(v_request.user_id,coalesce(nullif(trim(concat_ws(' ',v_profile.first_name,v_profile.last_name)),''),'IHLink Reseller'),coalesce(nullif(v_profile.phone,''),'Not provided'),'bronze','active',auth.uid(),now()) on conflict(user_id) do update set tier_code='bronze',status='active',approved_by=auth.uid(),approved_at=now(),updated_at=now(); else raise exception 'This upgrade cannot be customer-requested'; end if; update public.datasub_upgrade_requests set status='approved',reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=p_request_id; else update public.datasub_upgrade_requests set status='rejected',reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=p_request_id; end if; end; $$;
revoke all on function public.review_datasub_upgrade_request(uuid,boolean) from public,anon; grant execute on function public.review_datasub_upgrade_request(uuid,boolean) to authenticated;
